// GrantKind: Why an item was minted: one value per SendSystemItem / SendMail caller family
// (trimmed: 14 of 62).
type GrantKind uint8

const (
	// GrantKindUnknown: No kind reached the row; never an item_created row, the untyped byte of mail rows.
	GrantKindUnknown GrantKind = 0
	// GrantKindBuybackDelivery: CDPCoreClient::OnReceiveBuyBackResponse.
	GrantKindBuybackDelivery GrantKind = 1
	// GrantKindBuffReward: IBuffItemBase::Release.
	GrantKindBuffReward GrantKind = 2
	// GrantKindLevelUpGift: The CEventLua level-up gift, removed; historical rows keep the code.
	// Retired.
	GrantKindLevelUpGift GrantKind = 3
	// GrantKindBossRewardMail: GameEventGeneral::OnBossKilled (server-dungeon raid currency).
	GrantKindBossRewardMail GrantKind = 14
	// GrantKindWorldBossRewardMail: OnWorldBossKilled, removed with the WorldBoss system on 2026-09-03.
	// Retired.
	GrantKindWorldBossRewardMail GrantKind = 15
	// GrantKindEventReward: Rainbow race, secret room, Heistia, PvP event rewards; mailed remainders.
	GrantKindEventReward GrantKind = 16
	// GrantKindMailReturn: Not a mint: a returned, unclaimed or would-not-fit mail re-posts existing items.
	GrantKindMailReturn GrantKind = 22
	// GrantKindPerinOverflow: MoneyState::HandleMoneyIn's split-on-credit perin mint.
	GrantKindPerinOverflow GrantKind = 23
	// GrantKindPlayerMail: Not a mint: a player-to-player mail's items, seen from the mail side.
	GrantKindPlayerMail GrantKind = 27
	// GrantKindFarmHarvest: FarmManager::ClaimModel, farm production granted to the inventory.
	GrantKindFarmHarvest GrantKind = 35
	// GrantKindStarterItem: CDbManager::CreatePlayer: the starting items, DatabaseServer.
	GrantKindStarterItem GrantKind = 47
	// GrantKindGuildDisbandBank: The guild disband payout mail, removed; historical mail rows keep the code.
	// Retired.
	GrantKindGuildDisbandBank GrantKind = 48
	// GrantKindAuctionEscrowRecovery: An Azuria escrow re-mailed after a restart: a possible duplicate of a release.
	GrantKindAuctionEscrowRecovery GrantKind = 59
)

